// At the top of your file
import React, { useState, useEffect, useRef, useCallback } from 'react';
import { 
    Menu, Box, Linkedin, Twitter, GitHub, Mail, Phone, Facebook, 
    Instagram, Home, Info, Users, Folder, Activity, TrendingUp, Settings, MapPin 
} from 'react-feather';

// ------------------------------------------------------------------
// 1. CUSTOM HOOK FOR SCROLL ANIMATIONS
// ------------------------------------------------------------------
const useRevealOnScroll = (delay = 0) => {
    const elementRef = useRef(null);

    useEffect(() => {
        const currentElement = elementRef.current;
        if (!currentElement) return;

        if (delay > 0) {
            currentElement.style.transitionDelay = `${delay}ms`;
        }
        
        const observer = new IntersectionObserver(
            ([entry]) => {
                if (entry.isIntersecting) {
                    entry.target.classList.add('is-visible');
                    observer.unobserve(entry.target);
                }
            },
            { threshold: 0.1 }
        );

        observer.observe(currentElement);

        return () => {
            if (currentElement) {
                observer.unobserve(currentElement);
            }
        };
    }, [delay]);

    return elementRef;
};


// ------------------------------------------------------------------
// 2. HEADER COMPONENT
// ------------------------------------------------------------------
const Header = () => {
    return (
        <header className="sticky top-0 z-50 w-full bg-white/80 backdrop-blur-lg border-b border-slate-200/80">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <nav className="flex justify-between items-center h-16">
                    <a href="#hero" className="flex items-center gap-2 text-xl md:text-2xl font-bold text-blue-600">
                        <Box size={28} />
                        <span className="hidden sm:inline">Center for AI-IoT Innovation</span>
                        <span className="sm:hidden">AI-IoT Center</span>
                    </a>
                    <div className="hidden md:flex items-center space-x-4">
                        <ul className="flex items-center space-x-8">
                            <li><a href="#about" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">About</a></li>
                            <li><a href="#faculty" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">Faculty</a></li>
                            <li><a href="#projects" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">Projects</a></li>
                            <li><a href="#contact" className="text-slate-600 hover:text-blue-600 font-medium transition duration-300">Contact</a></li>
                        </ul>
                        <div className="flex items-center space-x-2">
                            <a href="https://airaware-app-gcw7.onrender.com/" target="_blank" rel="noopener noreferrer" className="bg-green-500 hover:bg-green-600 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AirAware</a>
                            <a href="https://app.aiiot.it.com/aws" target="_blank" rel="noopener noreferrer" className="bg-blue-600 hover:bg-blue-700 text-white font-semibold py-2 px-4 rounded-lg shadow-md hover:shadow-lg transition duration-300 transform hover:-translate-y-0.5">AWS</a>
                        </div>
                    </div>
                    <button className="md:hidden text-slate-600 hover:text-blue-600" aria-label="Open menu">
                        <Menu />
                    </button>
                </nav>
            </div>
        </header>
    );
};


// ------------------------------------------------------------------
// 3. HERO SECTION COMPONENT (WITH CAROUSEL)
// ------------------------------------------------------------------
const Hero = () => {
    const [heroImages, setHeroImages] = useState([]);
    const [currentImageIndex, setCurrentImageIndex] = useState(0);
    const autoSlideIntervalRef = useRef(null);

    const sectionRef = useRevealOnScroll();
    const titleRef = useRevealOnScroll(150);
    const ctaRef = useRevealOnScroll(300);
    const imageContainerRef = useRevealOnScroll(450);

    useEffect(() => {
        fetch('/carousel-images/carousel-images.json')
            .then(response => response.ok ? response.json() : Promise.reject(response))
            .then(data => data.length > 0 && setHeroImages(data))
            .catch(error => {
                console.error("Could not load carousel images:", error);
                setHeroImages([{ src: "https://placehold.co/1200x600/f0f9ff/334155?text=Image+Not+Available", alt: "Image not available" }]);
            });
    }, []);

    const changeImage = useCallback((index) => {
    const imageElement = document.getElementById('hero-image');
    if (imageElement) {
        imageElement.style.opacity = '0.4';
        imageElement.style.transform = 'scale(1.03)';
        setTimeout(() => {
            setCurrentImageIndex(index);
            imageElement.style.opacity = '1';
            imageElement.style.transform = 'scale(1)';
        }, 500);
    }
}, []);
    
    const startAutoSlide = useCallback(() => {
    stopAutoSlide(); // Assuming stopAutoSlide is defined outside and stable
    autoSlideIntervalRef.current = setInterval(() => {
        // Use the functional update form to avoid dependency on currentImageIndex
        setCurrentImageIndex(prevIndex => (prevIndex + 1) % heroImages.length);
    }, 4000);
}, [heroImages.length]);

    const stopAutoSlide = () => {
        if (autoSlideIntervalRef.current) {
            clearInterval(autoSlideIntervalRef.current);
        }
    };
    
    useEffect(() => {
        if (heroImages.length > 1) {
            startAutoSlide();
        }
        return () => stopAutoSlide();
    }, [heroImages.length]);

    const goToSlide = (index) => {
        changeImage(index);
        startAutoSlide();
    };

    if (heroImages.length === 0) return null;

    return (
        <section id="hero" className="relative hero-gradient py-20 md:py-32">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 text-center">
                <h1 ref={sectionRef} className="text-4xl md:text-6xl font-extrabold text-slate-800 mb-4 leading-tight reveal-on-scroll">
                    <span className="block text-2xl md:text-4xl font-medium text-slate-600">Sponsored by</span>
                    <span className="text-blue-600">Ministry of Electronics and Information Technology</span>
                </h1>
                <p ref={titleRef} className="text-lg md:text-xl text-slate-600 mb-10 max-w-3xl mx-auto reveal-on-scroll">
                    The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI).
                </p>
                <div ref={ctaRef} className="flex flex-col sm:flex-row justify-center items-center gap-4 mb-12 reveal-on-scroll">
                    <a href="#projects" className="w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105">Explore Projects</a>
                    <a href="#about" className="w-full sm:w-auto bg-white hover:bg-slate-100 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105">Learn More</a>
                </div>
                
                <div ref={imageContainerRef} id="hero-image-container" className="relative max-w-5xl mx-auto reveal-on-scroll" onMouseEnter={stopAutoSlide} onMouseLeave={startAutoSlide}>
                    <div className="absolute -inset-2 bg-gradient-to-r from-blue-400 to-indigo-500 rounded-2xl blur-lg opacity-25"></div>
                    <div className="relative w-full h-auto overflow-hidden rounded-xl shadow-2xl">
                        <img id="hero-image" src={heroImages[currentImageIndex]?.src} alt={heroImages[currentImageIndex]?.alt} width="1200" height="600" className="w-full h-auto object-cover" />
                    </div>
                    <div id="carousel-indicators" className="flex justify-center mt-6 space-x-3">
                        {heroImages.map((_, index) => (
                            <div key={index} className={`indicator w-3 h-3 rounded-full cursor-pointer ${index === currentImageIndex ? 'bg-blue-600 active' : 'bg-blue-300'}`} onClick={() => goToSlide(index)}></div>
                        ))}
                    </div>
                </div>
            </div>
        </section>
    );
};


// ------------------------------------------------------------------
// 4. ABOUT SECTION COMPONENT
// ------------------------------------------------------------------
const About = () => {
    const titleRef = useRevealOnScroll();
    const imageRef = useRevealOnScroll();
    const textRef = useRevealOnScroll(150);

    return (
        <section id="about" className="py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div ref={titleRef} className="text-center mb-12 reveal-on-scroll">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">About Our Center</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">Pioneering research where intelligence meets connectivity.</p>
                </div>
                <div className="grid md:grid-cols-2 gap-12 items-center">
                    <div ref={imageRef} className="reveal-on-scroll">
                        <div className="rounded-xl overflow-hidden shadow-lg border border-slate-200">
                            <img src="/carousel-images/1 (4).jpg" alt="Collaborative team working in a modern tech lab" loading="lazy" width="800" height="600" className="w-full h-auto object-cover"/>
                        </div>
                    </div>
                    <div ref={textRef} className="text-lg text-slate-600 space-y-6 reveal-on-scroll">
                        <p>The Center for AI IoT Innovation is a facility focused on the integration of electronics hardware design with artificial intelligence (AI) and explainable AI (XAI). The lab is equipped with hardware development tools, computing systems, and educational resources to support research and development in this area. The center provides resources for both theoretical research and practical applications, aiming to advance the integration of AI technologies with IoT systems.</p>
                        <p>We provide a state-of-the-art environment equipped with powerful computing resources and hardware development tools. This fosters a culture of innovation, empowering researchers and students to build the next generation of smart solutions.</p>
                    </div>
                </div>
            </div>
        </section>
    );
};


// ------------------------------------------------------------------
// 5. FACULTY SECTION COMPONENT
// ------------------------------------------------------------------
const Faculty = () => {
    const titleRef = useRevealOnScroll();
    const facultyMembers = [
        { name: 'Dr. Ajay Kumar', role: 'Principal Investigator', img: '/faculties/ajay.jpeg', link: 'https://www.adishankara.ac.in/department/faculty/25', desc: 'Dr. Ajay Kumar is an Associate Professor at ASIET with a PhD in Electronics and Communication Engineering. His research interests include IoT and Wireless Sensor Networks.', socials: { linkedin: '#', twitter: '#' } },
        { name: 'Mr. Albins Paul', role: 'Co-Investigator', img: '/faculties/albins.jpg', link: 'https://www.adishankara.ac.in/department/faculty/66', desc: 'Assistant Professor at ASIET\'s ECE Department, specializing in Microwave & Television Engineering.', socials: { linkedin: '#', github: '#' } },
        { name: 'Prof. P.V. Rajaraman', role: 'Co-Investigator', img: '/faculties/rajaraman.jpg', link: 'https://www.adishankara.ac.in/department/faculty/375', desc: 'Assistant Professor, CTO, and Head of the AI Department at ASIET. He specializes in NLP and XAI, has multiple publications, and is currently pursuing his Ph.D.', socials: { linkedin: '#', twitter: '#' } },
        { name: 'Mr. Abhijith Pm', role: 'Project Associate', img: '/faculties/abhijith.jpeg', link: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in', desc: null, socials: { linkedin: 'https://www.linkedin.com/in/abhijithpm-embedded-engineer/?originalSubdomain=in', twitter: '#' } },
        { name: 'Mrs. Hasna Hameed', role: 'Project Associate', img: '/faculties/hasna2.JPG', link: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/', desc: null, socials: { linkedin: 'https://www.linkedin.com/in/hasna-hameed-31b0b6227/', twitter: '#' } },
        { name: 'Ms. Arathy Surendran', role: 'Project Associate', img: '/faculties/arathy.JPG', link: 'https://www.linkedin.com/in/arathy-surendran/', desc: null, socials: { linkedin: 'https://www.linkedin.com/in/arathy-surendran/', twitter: '#' } },
        { name: 'Mr. Bhagyaraj J', role: 'Project Assistant', img: '/faculties/bhagyaraj.jpeg', link: '#', desc: null, socials: { linkedin: '#', github: '#' } },
        { name: 'Mr. Amaljith N Raj', role: 'Project Assistant', img: '/faculties/amaljith.JPG', link: '#', desc: null, socials: { linkedin: '#', github: '#' } },
        { name: 'Mrs. Jebina EA', role: 'Project Assistant', img: '/faculties/jibinaea.jpeg', link: '#', desc: null, socials: { linkedin: '#', github: '#' } }
    ];

    const FacultyCard = ({ member, delay }) => {
        const cardRef = useRevealOnScroll(delay);
        return (
            <div ref={cardRef} className="text-center bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl reveal-on-scroll">
                <a href={member.link} target="_blank" rel="noopener noreferrer" className="block">
                    <img className="w-32 h-32 mx-auto rounded-full mb-4 object-cover shadow-lg" src={member.img} alt={`Photo of ${member.name}`} loading="lazy" width="128" height="128" onError={(e) => { e.target.onerror = null; e.target.src = 'https://placehold.co/128x128/e0e0e0/000000?text=Faculty'; }} />
                </a>
                <a href={member.link} target="_blank" rel="noopener noreferrer" className="hover:text-blue-800 transition duration-300"><h4 className="text-xl font-bold text-blue-700">{member.name}</h4></a>
                <p className="text-slate-500 font-medium mb-2">{member.role}</p>
                <p className={`text-slate-600 text-sm mb-4 ${!member.desc ? 'h-10' : ''}`}>{member.desc}</p>
                <div className="flex justify-center space-x-4">
                    {member.socials.linkedin && <a href={member.socials.linkedin} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500" aria-label="LinkedIn"><Linkedin /></a>}
                    {member.socials.twitter && <a href={member.socials.twitter} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500" aria-label="Twitter"><Twitter /></a>}
                    // Corrected version
{member.socials.github && <a href={member.socials.github} target="_blank" rel="noopener noreferrer" className="text-slate-400 hover:text-blue-500" aria-label="GitHub"><GitHub /></a>}
                </div>
            </div>
        );
    };

    return (
        <section id="faculty" className="py-20 bg-slate-50">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div ref={titleRef} className="text-center mb-12 reveal-on-scroll">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Meet Our Expert Faculty</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">The brilliant minds leading our research and innovation.</p>
                </div>
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                    {facultyMembers.map((member, index) => (
                        <FacultyCard key={member.name} member={member} delay={index * 150} />
                    ))}
                </div>
            </div>
        </section>
    );
};


// ------------------------------------------------------------------
// 6. PROJECTS SECTION COMPONENT
// ------------------------------------------------------------------
const Projects = () => {
    const titleRef = useRevealOnScroll();
    const projectData = [
        { title: 'Intelligent Sensor Module', img: '/sensor_modules/module3.jpg', desc: 'Developing a smart sensor module for real-time monitoring and management of environmental pollutants.' },
        { title: 'Smart Water Level Monitoring', img: '/sensor_modules/water.png', desc: 'A robust solution for monitoring water levels with an integrated alert system to mitigate flood risks.' },
        { title: 'Digital Water Distribution', img: '/sensor_modules/water_authorityy.jpeg', desc: 'Creating a digital twin to efficiently monitor and manage water distribution networks in urban areas.' },
        { title: 'Startup & Skill Development', img: '/sensor_modules/skill.jpg', desc: 'Fostering a vibrant startup ecosystem and providing skill development programs centered around our IoT solutions.' },
        { title: 'Explainable AI Software', img: '/sensor_modules/ai.jpeg', desc: 'Building analysis software based on Explainable AI (XAI) to bring transparency and trust to complex IoT systems.' }
    ];
    
    const ProjectCard = ({ project, delay }) => {
        const cardRef = useRevealOnScroll(delay);
        return (
            <div ref={cardRef} className="bg-white p-6 rounded-xl shadow-md border border-slate-200 transform transition duration-300 hover:-translate-y-2 hover:shadow-xl reveal-on-scroll">
                <img src={project.img} alt={project.title} className="w-full h-40 object-cover rounded-lg mb-4" loading="lazy" width="400" height="200" />
                <h4 className="text-xl font-bold text-blue-700 mb-2">{project.title}</h4>
                <p className="text-slate-600 text-sm">{project.desc}</p>
            </div>
        );
    };

    return (
        <section id="projects" className="py-20 bg-white">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <div ref={titleRef} className="text-center mb-12 reveal-on-scroll">
                    <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800">Our Ongoing Projects</h2>
                    <p className="mt-4 text-lg text-slate-600 max-w-2xl mx-auto">From concept to reality, we're building solutions that matter.</p>
                </div>
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
                    {projectData.map((project, index) => (
                        <ProjectCard key={project.title} project={project} delay={index * 100} />
                    ))}
                </div>
            </div>
        </section>
    );
};


// ------------------------------------------------------------------
// 7. CONTACT SECTION COMPONENT
// ------------------------------------------------------------------
const Contact = () => {
    const sectionRef = useRevealOnScroll();
    return (
        <section id="contact" className="py-20 bg-slate-50">
            <div ref={sectionRef} className="max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 text-center reveal-on-scroll">
                <h2 className="text-3xl md:text-4xl font-extrabold text-slate-800 mb-4">Let's Build the Future Together</h2>
                <p className="text-lg text-slate-600 mb-8">Have a project in mind, a question, or want to collaborate? We'd love to hear from you.</p>
                <div className="flex flex-col sm:flex-row justify-center items-center gap-6">
                    <a href="mailto:aiiot@adishankara.ac.in" target="_blank" rel="noopener noreferrer" className="flex items-center justify-center gap-3 w-full sm:w-auto bg-blue-600 hover:bg-blue-700 text-white font-bold py-3 px-8 rounded-lg shadow-lg transition duration-300 transform hover:scale-105"><Mail className="w-5 h-5" /> Email Us</a>
                    <a href="tel:+919846900310" target="_blank" rel="noopener noreferrer" className="flex items-center justify-center gap-3 w-full sm:w-auto bg-slate-100 hover:bg-slate-200 text-slate-800 font-bold py-3 px-8 rounded-lg border border-slate-300 shadow-md transition duration-300 transform hover:scale-105"><Phone className="w-5 h-5" /> Call +919846900310</a>
                </div>
            </div>
        </section>
    );
};


// ------------------------------------------------------------------
// 8. FOOTER COMPONENT
